-- ==========================================================================
-- DIGEST-COPY RECUT: linesizing, question text only.
--
-- WHY. The live bank tells learners what "the digest" prints, points at numbered
-- SECTIONs of it, or names the authors' generator. The digest is the course
-- authors' internal reference file and no learner can see it. Each row below is
-- rewritten to name what the learner has: the course, the lesson, the lab or the
-- engine. Nothing else moves: no answer index, no option order, no ord, no
-- module key, no scope, no row count. Option lengths keep their rank.
--
-- SOURCE of the new text: the regenerated bank JSON under tools/course-banks/linesizing, built from its committed .py sources.
-- Rows: 17 (beginner 6, intermediate 3, advanced 8).
--
-- GUARDS. Each row is addressed by (app_slug, tier, scope, module_key, ord) and must
-- carry EITHER its published text exactly (then it is updated) OR the recut text
-- exactly (already applied, left alone). Anything else raises and the whole
-- transaction rolls back. Every update must touch exactly 1 row, and the course
-- must still hold its question count at the end. SAFE TO RE-RUN.
-- Published text was read from a replay of every question migration at origin/main,
-- FC9's recut (#181) and the B3 engine-strings recut (#184) included, so a row either
-- of those rewrote is expected to carry THEIR text: apply them first.
-- (docs/digest-recut/RECUT-linesizing.json carries OLD and NEW for every row).
-- ==========================================================================

do $$
declare
  v_state   text;
  v_count   integer;
  v_updated integer := 0;
  v_total   integer;
begin

  -- beginner m01-what-a-line-sizing-engine-does ord 1
  select case
           when prompt = 'A gathering system has four flowlines arriving at one header, and how the flow divides between them is unknown. What does this engine do with that problem?' and options = '["Nothing, because it sizes one line and nothing in it knows another line exists. A system of lines sharing a header is a network solve and lives in engines/production/networkSolve.js.", "It sizes the four in turn and then balances them, iterating over the four rates until the pressures the four lines report at the shared header agree with each other to a stated tolerance.", "It refuses, returning an object carrying an error string, because a shared header is one of the eighteen states Section 1 lists as having no answer in this method.", "It sizes the four separately and adds the four pressure drops together, and that sum is the header pressure a network solve would have returned for the same system."]'::jsonb and answer_index = 0 and explanation is not distinct from 'The engine takes a rate per line and returns what that one pipe spends. On OGBIA that is 25.660631 psi at 2.244621 ft/s, and every input on the call describes the one pipe.' then 'old'
           when prompt = 'A gathering system has four flowlines arriving at one header, and how the flow divides between them is unknown. What does this engine do with that problem?' and options = '["Nothing, because it sizes one line and nothing in it knows another line exists. A system of lines sharing a header is a network solve and lives in engines/production/networkSolve.js.", "It sizes the four in turn and then balances them, iterating over the four rates until the pressures the four lines report at the shared header agree with each other to a stated tolerance.", "It refuses, returning an object carrying an error string, because a shared header is one of the eighteen states listed as having no answer in this method.", "It sizes the four separately and adds the four pressure drops together, and that sum is the header pressure a network solve would have returned for the same system."]'::jsonb and answer_index = 0 and explanation is not distinct from 'The engine takes a rate per line and returns what that one pipe spends. On OGBIA that is 25.660631 psi at 2.244621 ft/s, and every input on the call describes the one pipe.' then 'new'
           else 'other' end
    into v_state
    from public.academy_quiz_questions where app_slug = 'linesizing' and tier = 'beginner' and scope = 'module' and module_key is not distinct from 'm01-what-a-line-sizing-engine-does' and ord = 1;
  if v_state is null then raise exception 'digest-copy recut, linesizing refused: no row for beginner m01-what-a-line-sizing-engine-does ord 1'; end if;
  if v_state = 'other' then raise exception 'digest-copy recut, linesizing refused: beginner m01-what-a-line-sizing-engine-does ord 1 matches neither its published nor its recut text'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions set prompt = 'A gathering system has four flowlines arriving at one header, and how the flow divides between them is unknown. What does this engine do with that problem?', options = '["Nothing, because it sizes one line and nothing in it knows another line exists. A system of lines sharing a header is a network solve and lives in engines/production/networkSolve.js.", "It sizes the four in turn and then balances them, iterating over the four rates until the pressures the four lines report at the shared header agree with each other to a stated tolerance.", "It refuses, returning an object carrying an error string, because a shared header is one of the eighteen states listed as having no answer in this method.", "It sizes the four separately and adds the four pressure drops together, and that sum is the header pressure a network solve would have returned for the same system."]'::jsonb, explanation = 'The engine takes a rate per line and returns what that one pipe spends. On OGBIA that is 25.660631 psi at 2.244621 ft/s, and every input on the call describes the one pipe.'
     where app_slug = 'linesizing' and tier = 'beginner' and scope = 'module' and module_key is not distinct from 'm01-what-a-line-sizing-engine-does' and ord = 1;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'digest-copy recut, linesizing refused: beginner m01-what-a-line-sizing-engine-does ord 1 updated % rows', v_count; end if;
    v_updated := v_updated + 1;
  end if;

  -- beginner m01-what-a-line-sizing-engine-does ord 4
  select case
           when prompt = 'A liquid line call comes back with the message that it needs positive rate, bore, length, density and viscosity. How much has the caller been told about which input was at fault?' and options = '["That the rate was at fault, since the message lists the five inputs in the order the guard tests them and the offending one is always named first.", "That exactly one of the five was missing, since a value that arrived negative produces a separate message naming the sign rather than this one.", "That the bore, the length and the density were all usable, since the message names only the inputs the guard could not accept and leaves out the ones it could.", "Nothing about which one. Five of the eighteen states Section 1 lists produce that identical string, and it states the contract the five inputs share rather than pointing at the offender."]'::jsonb and answer_index = 3 and explanation is not distinct from 'A missing rate, a negative rate, a missing bore, a missing length and a missing viscosity all return that one string. The message describes the contract and the caller still has to read the row.' then 'old'
           when prompt = 'A liquid line call comes back with the message that it needs positive rate, bore, length, density and viscosity. How much has the caller been told about which input was at fault?' and options = '["That the rate was at fault, since the message lists the five inputs in the order the guard tests them and the offending one is always named first.", "That exactly one of the five was missing, since a value that arrived negative produces a separate message naming the sign rather than this one.", "That the bore, the length and the density were all usable, since the message names only the inputs the guard could not accept and leaves out the ones it could.", "Nothing about which one. Five of the eighteen states the course lists produce that identical string, and it states the contract the five inputs share rather than pointing at the offender."]'::jsonb and answer_index = 3 and explanation is not distinct from 'A missing rate, a negative rate, a missing bore, a missing length and a missing viscosity all return that one string. The message describes the contract and the caller still has to read the row.' then 'new'
           else 'other' end
    into v_state
    from public.academy_quiz_questions where app_slug = 'linesizing' and tier = 'beginner' and scope = 'module' and module_key is not distinct from 'm01-what-a-line-sizing-engine-does' and ord = 4;
  if v_state is null then raise exception 'digest-copy recut, linesizing refused: no row for beginner m01-what-a-line-sizing-engine-does ord 4'; end if;
  if v_state = 'other' then raise exception 'digest-copy recut, linesizing refused: beginner m01-what-a-line-sizing-engine-does ord 4 matches neither its published nor its recut text'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions set prompt = 'A liquid line call comes back with the message that it needs positive rate, bore, length, density and viscosity. How much has the caller been told about which input was at fault?', options = '["That the rate was at fault, since the message lists the five inputs in the order the guard tests them and the offending one is always named first.", "That exactly one of the five was missing, since a value that arrived negative produces a separate message naming the sign rather than this one.", "That the bore, the length and the density were all usable, since the message names only the inputs the guard could not accept and leaves out the ones it could.", "Nothing about which one. Five of the eighteen states the course lists produce that identical string, and it states the contract the five inputs share rather than pointing at the offender."]'::jsonb, explanation = 'A missing rate, a negative rate, a missing bore, a missing length and a missing viscosity all return that one string. The message describes the contract and the caller still has to read the row.'
     where app_slug = 'linesizing' and tier = 'beginner' and scope = 'module' and module_key is not distinct from 'm01-what-a-line-sizing-engine-does' and ord = 4;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'digest-copy recut, linesizing refused: beginner m01-what-a-line-sizing-engine-does ord 4 updated % rows', v_count; end if;
    v_updated := v_updated + 1;
  end if;

  -- beginner m01-what-a-line-sizing-engine-does ord 8
  select case
           when prompt = 'gc is reported as 32.174000 lbm ft per lbf s2. How was that figure obtained for this digest?' and options = '["By reading it off the module, which exports gc along with the other constants the chain needs so that a caller can reproduce any step of the arithmetic by hand.", "By measuring it out of the engine, as the density times the velocity squared over twice 144 times the fittings loss at a resistance sum of one, from 2.244621 ft/s and 0.029634 psi.", "By typing the published value, since gc is a definition of the pound rather than anything an engine computes, so no question that could be put to the engine would ever return the figure itself.", "By dividing the friction loss of 25.660631 psi by the velocity head at a resistance sum of one, which cancels the length and the friction factor between them and leaves gc standing on its own."]'::jsonb and answer_index = 1 and explanation is not distinct from 'gc reconciles the pound as a mass with the pound as a force. Isolating it needs a call whose only loss is the fittings term, which is why the resistance sum of one is used.' then 'old'
           when prompt = 'gc is reported as 32.174000 lbm ft per lbf s2. How was that figure obtained for this course?' and options = '["By reading it off the module, which exports gc along with the other constants the chain needs so that a caller can reproduce any step of the arithmetic by hand.", "By measuring it out of the engine, as the density times the velocity squared over twice 144 times the fittings loss at a resistance sum of one, from 2.244621 ft/s and 0.029634 psi.", "By typing the published value, since gc is a definition of the pound rather than anything an engine computes, so no question that could be put to the engine would ever return the figure itself.", "By dividing the friction loss of 25.660631 psi by the velocity head at a resistance sum of one, which cancels the length and the friction factor between them and leaves gc standing on its own."]'::jsonb and answer_index = 1 and explanation is not distinct from 'gc reconciles the pound as a mass with the pound as a force. Isolating it needs a call whose only loss is the fittings term, which is why the resistance sum of one is used.' then 'new'
           else 'other' end
    into v_state
    from public.academy_quiz_questions where app_slug = 'linesizing' and tier = 'beginner' and scope = 'module' and module_key is not distinct from 'm01-what-a-line-sizing-engine-does' and ord = 8;
  if v_state is null then raise exception 'digest-copy recut, linesizing refused: no row for beginner m01-what-a-line-sizing-engine-does ord 8'; end if;
  if v_state = 'other' then raise exception 'digest-copy recut, linesizing refused: beginner m01-what-a-line-sizing-engine-does ord 8 matches neither its published nor its recut text'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions set prompt = 'gc is reported as 32.174000 lbm ft per lbf s2. How was that figure obtained for this course?', options = '["By reading it off the module, which exports gc along with the other constants the chain needs so that a caller can reproduce any step of the arithmetic by hand.", "By measuring it out of the engine, as the density times the velocity squared over twice 144 times the fittings loss at a resistance sum of one, from 2.244621 ft/s and 0.029634 psi.", "By typing the published value, since gc is a definition of the pound rather than anything an engine computes, so no question that could be put to the engine would ever return the figure itself.", "By dividing the friction loss of 25.660631 psi by the velocity head at a resistance sum of one, which cancels the length and the friction factor between them and leaves gc standing on its own."]'::jsonb, explanation = 'gc reconciles the pound as a mass with the pound as a force. Isolating it needs a call whose only loss is the fittings term, which is why the resistance sum of one is used.'
     where app_slug = 'linesizing' and tier = 'beginner' and scope = 'module' and module_key is not distinct from 'm01-what-a-line-sizing-engine-does' and ord = 8;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'digest-copy recut, linesizing refused: beginner m01-what-a-line-sizing-engine-does ord 8 updated % rows', v_count; end if;
    v_updated := v_updated + 1;
