  -- beginner m01-what-a-line-sizing-engine-does ord 9
  select case
           when prompt = 'Why does this digest measure gc, the centipoise, the barrel and the day out of the engine rather than printing their published values?' and options = '["Because the engine''s own values differ slightly from the published ones, and what the chain actually used is what a reader has to be given to reproduce any figure in it.", "Because each of the four is a derived group with no published value behind it anywhere, so measuring it out of the engine is the only route to any figure at all.", "Because the module keeps those constants to itself, so a number typed into a teaching file would not be an engine return.", "Because the module exports them under names this digest has no way to import, so asking the engine a question about itself is how a present but unreachable value is recovered."]'::jsonb and answer_index = 2 and explanation is not distinct from 'One centipoise comes back as 6.7197000000e-4 lbm per ft per s and one barrel as 5.6145833333333 cubic feet, each recovered by choosing inputs that isolate it.' then 'old'
           when prompt = 'Why does this course measure gc, the centipoise, the barrel and the day out of the engine rather than printing their published values?' and options = '["Because the engine''s own values differ slightly from the published ones, and what the chain actually used is what a reader has to be given to reproduce any figure in it.", "Because each of the four is a derived group with no published value behind it anywhere, so measuring it out of the engine is the only route to any figure at all.", "Because the module keeps those constants to itself, so a number typed into a teaching file would not be an engine return.", "Because the module exports them under names this course has no way to import, so asking the engine a question about itself is how a present but unreachable value is recovered."]'::jsonb and answer_index = 2 and explanation is not distinct from 'One centipoise comes back as 6.7197000000e-4 lbm per ft per s and one barrel as 5.6145833333333 cubic feet, each recovered by choosing inputs that isolate it.' then 'new'
