    into v_state
    from public.academy_quiz_questions where app_slug = 'linesizing' and tier = 'beginner' and scope = 'module' and module_key is not distinct from 'm01-what-a-line-sizing-engine-does' and ord = 9;
  if v_state is null then raise exception 'digest-copy recut, linesizing refused: no row for beginner m01-what-a-line-sizing-engine-does ord 9'; end if;
  if v_state = 'other' then raise exception 'digest-copy recut, linesizing refused: beginner m01-what-a-line-sizing-engine-does ord 9 matches neither its published nor its recut text'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions set prompt = 'Why does this course measure gc, the centipoise, the barrel and the day out of the engine rather than printing their published values?', options = '["Because the engine''s own values differ slightly from the published ones, and what the chain actually used is what a reader has to be given to reproduce any figure in it.", "Because each of the four is a derived group with no published value behind it anywhere, so measuring it out of the engine is the only route to any figure at all.", "Because the module keeps those constants to itself, so a number typed into a teaching file would not be an engine return.", "Because the module exports them under names this course has no way to import, so asking the engine a question about itself is how a present but unreachable value is recovered."]'::jsonb, explanation = 'One centipoise comes back as 6.7197000000e-4 lbm per ft per s and one barrel as 5.6145833333333 cubic feet, each recovered by choosing inputs that isolate it.'
     where app_slug = 'linesizing' and tier = 'beginner' and scope = 'module' and module_key is not distinct from 'm01-what-a-line-sizing-engine-does' and ord = 9;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'digest-copy recut, linesizing refused: beginner m01-what-a-line-sizing-engine-does ord 9 updated % rows', v_count; end if;
    v_updated := v_updated + 1;
  end if;

  -- beginner m01-what-a-line-sizing-engine-does ord 12
  select case
           when prompt = 'On the liquid side, one of the states Section 1 lists is about the shape of the input rather than about a physical impossibility. Which is it, and how does it arrive?' and options = '["A liquid line handed a negative rate, and it arrives as a thrown exception, because a sign error is a fault in the calling code rather than a state the method has no answer for.", "A traverse handed no profile segment, and it arrives exactly as the others do, as an object carrying { error: \"a traverse needs at least one profile segment\" }.", "A wall specified to a design code that does not exist, and it arrives as a null return so that a caller can test for it without having to read and compare a message string.", "A pig that does not move, and it arrives as a returned run time of zero hours, which a caller reads as the line having no length for the sphere to cross."]'::jsonb and answer_index = 1 and explanation is not distinct from 'Whether the method was handed nonsense or handed a state it cannot size, the return is an object, the property is error, and the string says what was wanted.' then 'old'
           when prompt = 'On the liquid side, one of the states the course lists is about the shape of the input rather than about a physical impossibility. Which is it, and how does it arrive?' and options = '["A liquid line handed a negative rate, and it arrives as a thrown exception, because a sign error is a fault in the calling code rather than a state the method has no answer for.", "A traverse handed no profile segment, and it arrives exactly as the others do, as an object carrying { error: \"a traverse needs at least one profile segment\" }.", "A wall specified to a design code that does not exist, and it arrives as a null return so that a caller can test for it without having to read and compare a message string.", "A pig that does not move, and it arrives as a returned run time of zero hours, which a caller reads as the line having no length for the sphere to cross."]'::jsonb and answer_index = 1 and explanation is not distinct from 'Whether the method was handed nonsense or handed a state it cannot size, the return is an object, the property is error, and the string says what was wanted.' then 'new'
           else 'other' end
    into v_state
    from public.academy_quiz_questions where app_slug = 'linesizing' and tier = 'beginner' and scope = 'module' and module_key is not distinct from 'm01-what-a-line-sizing-engine-does' and ord = 12;
  if v_state is null then raise exception 'digest-copy recut, linesizing refused: no row for beginner m01-what-a-line-sizing-engine-does ord 12'; end if;
