  if v_state = 'old' then
    update public.academy_quiz_questions set prompt = 'On the liquid side, one of the states the course lists is about the shape of the input rather than about a physical impossibility. Which is it, and how does it arrive?', options = '["A liquid line handed a negative rate, and it arrives as a thrown exception, because a sign error is a fault in the calling code rather than a state the method has no answer for.", "A traverse handed no profile segment, and it arrives exactly as the others do, as an object carrying { error: \"a traverse needs at least one profile segment\" }.", "A wall specified to a design code that does not exist, and it arrives as a null return so that a caller can test for it without having to read and compare a message string.", "A pig that does not move, and it arrives as a returned run time of zero hours, which a caller reads as the line having no length for the sphere to cross."]'::jsonb, explanation = 'Whether the method was handed nonsense or handed a state it cannot size, the return is an object, the property is error, and the string says what was wanted.'
     where app_slug = 'linesizing' and tier = 'beginner' and scope = 'module' and module_key is not distinct from 'm01-what-a-line-sizing-engine-does' and ord = 12;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'digest-copy recut, linesizing refused: beginner m01-what-a-line-sizing-engine-does ord 12 updated % rows', v_count; end if;
    v_updated := v_updated + 1;
  end if;

  -- beginner m06-the-associate-reading ord 6
  select case
           when prompt = 'Nothing in the OGBIA line compresses, so a barrel entering it is a barrel leaving it. What would change if it did compress?' and options = '["The engine would refuse the line, since a density that varies along the run is one of the eighteen states Section 1 lists as having no answer at all in this method.", "Only the erosional ceiling would move, since it is the one figure in the tier built from the density, and the friction chain reads the density solely through the Reynolds number.", "Nothing in the reported numbers, since the density is taken at the inlet and the loss is reported over the whole line, so compressibility would reach the answer only through the gradient.", "The density would depend on the pressure, which is the quantity being solved for."]'::jsonb and answer_index = 3 and explanation is not distinct from 'The velocity of 2.244621 ft/s stands at both ends because the density of 54.500000 lb/ft3 does. Let the fluid compress and the whole method changes shape.' then 'old'
           when prompt = 'Nothing in the OGBIA line compresses, so a barrel entering it is a barrel leaving it. What would change if it did compress?' and options = '["The engine would refuse the line, since a density that varies along the run is one of the eighteen states the course lists as having no answer at all in this method.", "Only the erosional ceiling would move, since it is the one figure in the tier built from the density, and the friction chain reads the density solely through the Reynolds number.", "Nothing in the reported numbers, since the density is taken at the inlet and the loss is reported over the whole line, so compressibility would reach the answer only through the gradient.", "The density would depend on the pressure, which is the quantity being solved for."]'::jsonb and answer_index = 3 and explanation is not distinct from 'The velocity of 2.244621 ft/s stands at both ends because the density of 54.500000 lb/ft3 does. Let the fluid compress and the whole method changes shape.' then 'new'
           else 'other' end
    into v_state
    from public.academy_quiz_questions where app_slug = 'linesizing' and tier = 'beginner' and scope = 'module' and module_key is not distinct from 'm06-the-associate-reading' and ord = 6;
