  -- intermediate m03-the-elevation-adjustment ord 6
  select case
           when prompt = 'The coefficient inside s is reported as 0.037500000000, and the digest says it was measured rather than typed. How was it obtained?' and options = '["The engine was asked for s at a gravity of one, a rise of 1000.000000 ft, an absolute temperature of one and a compressibility of one, and the 37.500000 it returned was divided by the thousand feet.", "The engine was asked for s at the SOKU conditions and at 1500.000000 ft of rise, and 0.0795976556 was divided by the gravity, the temperature and the compressibility in turn until only the elevation remained.", "The coefficient was read off the ratio of the two equivalent length factors at 1500.000000 ft of rise and 1500.000000 ft of fall, which isolates it from everything else in the group.", "The coefficient was recovered from the base conditions of 520.000000 degR and 14.650000 psia, which is where the field units of the published forms enter the elevation term."]'::jsonb and answer_index = 0 and explanation is not distinct from 'Setting three of the four inputs to one leaves the coefficient and the elevation change, so dividing by the elevation change leaves the coefficient. It is an engine return rather than a figure copied beside one.' then 'old'
           when prompt = 'The coefficient inside s is reported as 0.037500000000, and the course says it was measured rather than typed. How was it obtained?' and options = '["The engine was asked for s at a gravity of one, a rise of 1000.000000 ft, an absolute temperature of one and a compressibility of one, and the 37.500000 it returned was divided by the thousand feet.", "The engine was asked for s at the SOKU conditions and at 1500.000000 ft of rise, and 0.0795976556 was divided by the gravity, the temperature and the compressibility in turn until only the elevation remained.", "The coefficient was read off the ratio of the two equivalent length factors at 1500.000000 ft of rise and 1500.000000 ft of fall, which isolates it from everything else in the group.", "The coefficient was recovered from the base conditions of 520.000000 degR and 14.650000 psia, which is where the field units of the published forms enter the elevation term."]'::jsonb and answer_index = 0 and explanation is not distinct from 'Setting three of the four inputs to one leaves the coefficient and the elevation change, so dividing by the elevation change leaves the coefficient. It is an engine return rather than a figure copied beside one.' then 'new'
