     where app_slug = 'linesizing' and tier = 'intermediate' and scope = 'module' and module_key is not distinct from 'm03-the-elevation-adjustment' and ord = 6;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'digest-copy recut, linesizing refused: intermediate m03-the-elevation-adjustment ord 6 updated % rows', v_count; end if;
