  -- advanced m05-what-the-method-does-not-know ord 14
  select case
           when prompt = 'Why is an absence harder for a reader to notice than a held item?' and options = '["A held item announces itself in writing, and an absence has no field to attach a warning to, so a two-phase line returns a velocity, a Reynolds number, a friction factor and a pressure drop that are all arithmetically correct for a single-phase fluid.", "An absence is refused by the engine in the ordinary way, so a reader sees only an error string and has no figure in front of them to question.", "A held item is graded and an absence is not, so a reader meets the held item in the capstone and never meets the absence at all.", "An absence is recorded in the digest under a different heading from the held items, and a reader working from the lessons alone never reaches that part of the digest."]'::jsonb and answer_index = 0 and explanation is not distinct from 'The engine cannot detect it, because a mixture density is a perfectly ordinary number. Nothing in the answer says the single-phase result is the wrong model rather than an imprecise one.' then 'old'
